implementation:
(* Single low-speed 20 mm out-and-back test cycle.
   Start only on a rising edge of GVL_Motion.xStartCycle.
   Travel is capped at 20 mm per leg and 10 mm/s. *)
rtCycle(CLK := GVL_Motion.xStartCycle);

fbPower(Axis         := Axis_1,
        Enable       := GVL_Motion.xEnable,
        bRegulatorOn := TRUE,
        bDriveStart  := TRUE);

fbReset(Axis := Axis_1, Execute := GVL_Motion.xReset);

IF GVL_Motion.xStop THEN
    xStopRun   := TRUE;
    fbCycleExec := FALSE;
    iCycle      := 0;
END_IF

IF fbPower.Error OR fbCycle.Error OR fbReset.Error OR fbStop.Error THEN
    iCycle      := 99;
    fbCycleExec := FALSE;
    xStopRun    := TRUE;
END_IF

fbStop(Axis         := Axis_1,
       Execute      := xStopRun,
       Deceleration := MIN(MAX(GVL_Motion.rDec, 10.0), 200.0));

IF xStopRun AND fbStop.Done THEN
    xStopRun := FALSE;
END_IF

tonDwell(IN := (iCycle = 20) OR (iCycle = 40),
         PT := GVL_Motion.tDwell);

CASE iCycle OF
    0:  (* Idle; one rising edge starts one round trip. *)
        fbCycleExec := FALSE;
        IF rtCycle.Q
           AND GVL_Motion.xEnable
           AND fbPower.Status
           AND NOT GVL_Motion.xAxisError
           AND NOT xStopRun
           AND (ABS(GVL_Motion.rStroke) > 0.0) THEN
            rCycleDist := MIN(ABS(GVL_Motion.rStroke), 20.0);
            fbCycleExec := TRUE;
            iCycle := 10;
        END_IF

    10: (* Forward leg. *)
        IF fbCycle.Done THEN
            fbCycleExec := FALSE;
            iCycle := 20;
        ELSIF fbCycle.Error THEN
            fbCycleExec := FALSE;
            iCycle := 99;
            xStopRun := TRUE;
        END_IF

    20: (* Dwell before return leg. *)
        IF tonDwell.Q AND NOT xStopRun THEN
            rCycleDist := -MIN(ABS(GVL_Motion.rStroke), 20.0);
            fbCycleExec := TRUE;
            iCycle := 30;
        END_IF

    30: (* Return leg. *)
        IF fbCycle.Done THEN
            fbCycleExec := FALSE;
            iCycle := 40;
        ELSIF fbCycle.Error THEN
            fbCycleExec := FALSE;
            iCycle := 99;
            xStopRun := TRUE;
        END_IF

    40: (* Dwell after returning to the start position, then finish. *)
        IF tonDwell.Q THEN
            iCycle := 0;
        END_IF

    99: (* Error latch; require a successful reset and completed stop. *)
        fbCycleExec := FALSE;
        IF GVL_Motion.xReset AND fbReset.Done AND NOT xStopRun THEN
            iCycle := 0;
        END_IF

ELSE
    iCycle := 99;
    fbCycleExec := FALSE;
    xStopRun := TRUE;
END_CASE

fbCycle(Axis         := Axis_1,
        Execute      := fbCycleExec AND NOT xStopRun,
        Distance     := rCycleDist,
        Velocity     := MIN(MAX(GVL_Motion.rVel, 1.0), 10.0),
        Acceleration := MIN(MAX(GVL_Motion.rAcc, 10.0), 200.0),
        Deceleration := MIN(MAX(GVL_Motion.rDec, 10.0), 200.0));

fbReadPos(Axis := Axis_1, Enable := TRUE);

GVL_Motion.xPowered    := fbPower.Status;
GVL_Motion.xBusy       := fbCycle.Busy OR fbStop.Busy;
GVL_Motion.xDisabled   := NOT fbPower.Status;
GVL_Motion.xStopping   := fbStop.Busy;
GVL_Motion.xStandStill := fbPower.Status AND NOT GVL_Motion.xBusy;
GVL_Motion.xAxisReady  := GVL_Motion.xStandStill AND NOT GVL_Motion.xAxisError;
GVL_Motion.xAxisError  := fbPower.Error OR fbCycle.Error OR fbReset.Error OR fbStop.Error;
GVL_Motion.xErrorStop  := GVL_Motion.xAxisError;
GVL_Motion.iState      := iCycle;
GVL_Motion.rActPos     := fbReadPos.Position;

declaration:
PROGRAM PLC_PRG
VAR
    (* ---- SoftMotion function block instances ---- *)
    fbPower    : MC_Power;            (* enable / disable the axis *)
    fbReset    : MC_Reset;            (* reset axis error *)
    fbStop     : MC_Stop;             (* stop and lock the axis *)
    fbJog      : MC_Jog;              (* jog *)
    fbMoveRel  : MC_MoveRelative;     (* single relative move *)
    fbMoveAbs  : MC_MoveAbsolute;     (* single absolute move *)
    fbCycle    : MC_MoveRelative;     (* auto cycle move *)
    fbReadPos  : MC_ReadActualPosition; (* position feedback *)
    fbReadStat : MC_ReadStatus;       (* axis state machine *)
    fbReadErr  : MC_ReadAxisError;    (* axis error code *)

    (* ---- edge detection ---- *)
    rtCycle    : R_TRIG;              (* auto cycle trigger *)

    (* ---- auto cycle ---- *)
    fbCycleExec: BOOL;                (* Execute for fbCycle *)
    rCycleDist : LREAL;               (* current segment distance *)
    iCycle     : INT := 0;            (* auto cycle step *)
    tonDwell   : TON;                 (* dwell at cycle ends *)

    (* ---- diagnostics ---- *)
    eLastErr   : SMC_ERROR;           (* latched last motion block error *)
	xDoReset: BOOL;
	xStopRun: BOOL;
	rRunDec: LREAL;
	xStartRun: BOOL;
	iStep: INT;
	fbMoveVel: MC_MoveVelocity;
	Axis: INT;
	Execute: BOOL;
	rRunVel: LREAL;
	rRunAcc: LREAL;
	Velocity: INT;
	Acceleration: INT;
	Deceleration: INT;
	Direction: INT;
	InVelocity: INT;
	xMoveExec: BOOL;
END_VAR
